import{_ as t,c as s,o as a,ah as i,am as o}from"./chunks/framework.CdwlI3v5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"_layout":"writeup","ctf":"WhiteHats CTF 2021","chal":"Eight Masketeers","category":"misc","flag":"WH2021{MY_MASKS_R_THE_BEST}","points":992,"solves":4},"headers":[],"relativePath":"writeups/2021/WhiteHats 2021/Eight Masketeers/2021-03-07-Eight Masketeers.md","filePath":"writeups/2021/WhiteHats 2021/Eight Masketeers/2021-03-07-Eight Masketeers.md"}'),r={name:"writeups/2021/WhiteHats 2021/Eight Masketeers/2021-03-07-Eight Masketeers.md"};function c(n,e,l,h,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<blockquote><p>Alice discovered a note (titled 8 MASKeteers) left behind by Bob after a lesson on bitwise operations.</p></blockquote><blockquote><p>She believes that it is some sort of the &quot;new bitwise masking technique which can extract large amount of information&quot; that Bob had been talking about during class.</p></blockquote><blockquote><p>Are you able to help Alice decode the message?</p></blockquote><p>Files given:</p><ul><li><a href="Mask.png">Mask.png</a></li></ul><p>Looking at the description, my first thought was that the image pixels was bitmasked and needed to poke it, however looking closer at the picture, the idea turns out to be very simple, as illustrated in the diagram below:</p><p><img src="'+o+'" alt="masking image"></p><p>Essentially the <code>&amp;</code> represents &#39;bitwise AND&#39; with the cells below and the <code>~</code> is bitwise NOT. Here we get <code>4d595f4d</code>, which we know are ASCII characters, hence we are on the right track, continuing this for every cell, we get <code>4d595f4d41534b535f525f5448455f42455354</code>, giving us the flag, <code>MY_MASKS_R_THE_BEST</code></p>',8)])])}const u=t(r,[["render",c]]);export{_ as __pageData,u as default};
